-- Session 2: admin-only application data and private gallery storage.
create extension if not exists pgcrypto;
create table if not exists public.admin_users (id uuid primary key references auth.users (id) on delete cascade, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.admin_users where id = auth.uid()); $$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated, service_role;
create table if not exists public.clients (id uuid primary key default gen_random_uuid(), name text not null check (char_length(trim(name)) between 1 and 200), email text, phone text, notes text, created_by uuid not null default auth.uid() references auth.users (id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.galleries (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients (id) on delete restrict, title text not null check (char_length(trim(title)) between 1 and 200), slug text not null check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), description text, event_date date, status text not null default 'draft' check (status in ('draft', 'published', 'archived')), created_by uuid not null default auth.uid() references auth.users (id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (slug));
create table if not exists public.folders (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries (id) on delete cascade, parent_folder_id uuid, name text not null check (char_length(trim(name)) between 1 and 200), slug text not null check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), sort_order integer not null default 0 check (sort_order >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (id, gallery_id), unique (gallery_id, parent_folder_id, slug), foreign key (parent_folder_id, gallery_id) references public.folders (id, gallery_id) on delete cascade);
create table if not exists public.photos (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries (id) on delete cascade, folder_id uuid not null, filename text not null check (char_length(trim(filename)) between 1 and 500), original_path text not null unique check (original_path !~ '^/'), preview_path text check (preview_path is null or preview_path !~ '^/'), thumbnail_path text check (thumbnail_path is null or thumbnail_path !~ '^/'), mime_type text not null check (mime_type like 'image/%'), bytes bigint not null check (bytes > 0), width integer check (width > 0), height integer check (height > 0), sort_order integer not null default 0 check (sort_order >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (id, gallery_id), foreign key (folder_id, gallery_id) references public.folders (id, gallery_id) on delete cascade);
create table if not exists public.selections (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries (id) on delete cascade, photo_id uuid not null, viewer_name text not null check (char_length(trim(viewer_name)) between 1 and 200), viewer_key_hash text not null check (char_length(viewer_key_hash) >= 32), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (gallery_id, photo_id, viewer_key_hash), foreign key (photo_id, gallery_id) references public.photos (id, gallery_id) on delete cascade);
create table if not exists public.photo_shares (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries (id) on delete cascade, photo_id uuid not null, token_hash text not null unique check (char_length(token_hash) >= 32), expires_at timestamptz, revoked_at timestamptz, created_by uuid not null default auth.uid() references auth.users (id) on delete restrict, created_at timestamptz not null default now(), foreign key (photo_id, gallery_id) references public.photos (id, gallery_id) on delete cascade, check (revoked_at is null or revoked_at >= created_at));
create table if not exists public.access_attempts (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries (id) on delete cascade, succeeded boolean not null, attempted_at timestamptz not null default now(), ip_hash text, user_agent text, failure_reason text check (failure_reason is null or char_length(failure_reason) <= 200));
create index if not exists galleries_client_id_idx on public.galleries (client_id);
create index if not exists folders_gallery_id_sort_order_idx on public.folders (gallery_id, sort_order, id);
create index if not exists photos_gallery_id_folder_id_sort_order_idx on public.photos (gallery_id, folder_id, sort_order, id);
create index if not exists selections_gallery_id_viewer_key_hash_idx on public.selections (gallery_id, viewer_key_hash);
create index if not exists photo_shares_gallery_id_idx on public.photo_shares (gallery_id);
create index if not exists access_attempts_gallery_id_attempted_at_idx on public.access_attempts (gallery_id, attempted_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
create trigger clients_set_updated_at before update on public.clients for each row execute procedure public.set_updated_at();
create trigger galleries_set_updated_at before update on public.galleries for each row execute procedure public.set_updated_at();
create trigger folders_set_updated_at before update on public.folders for each row execute procedure public.set_updated_at();
create trigger photos_set_updated_at before update on public.photos for each row execute procedure public.set_updated_at();
create trigger selections_set_updated_at before update on public.selections for each row execute procedure public.set_updated_at();
alter table public.admin_users enable row level security; alter table public.clients enable row level security; alter table public.galleries enable row level security; alter table public.folders enable row level security; alter table public.photos enable row level security; alter table public.selections enable row level security; alter table public.photo_shares enable row level security; alter table public.access_attempts enable row level security;
create policy "admin reads own membership" on public.admin_users for select to authenticated using (id = auth.uid());
create policy "admin manages clients" on public.clients for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin manages galleries" on public.galleries for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin manages folders" on public.folders for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin manages photos" on public.photos for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin manages selections" on public.selections for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin manages photo shares" on public.photo_shares for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin reads access attempts" on public.access_attempts for select to authenticated using (public.is_admin());
insert into storage.buckets (id, name, public) values ('client-gallery-assets', 'client-gallery-assets', false) on conflict (id) do update set public = false;
create policy "admin manages private gallery objects" on storage.objects for all to authenticated using (bucket_id = 'client-gallery-assets' and public.is_admin()) with check (bucket_id = 'client-gallery-assets' and public.is_admin());
